import { CheckoutService } from './src/checkout.js';

function banner(title) {
  console.log('\\n==== ' + title + ' ====');
}

async function run(name, fn) {
  try {
    await fn();
    console.log('PASS', name);
  } catch (err) {
    console.log('FAIL', name);
    console.log(String(err && err.stack || err));
  }
}

banner('1. sequential same key/payload identity and create-once');
await run('same order object and creates===1', async () => {
  let creates = 0;
  const service = new CheckoutService({
    async create(cart) {
      creates += 1;
      return { id: 'o1', cart };
    }
  });
  const cart = { sku: 1 };
  const a = await service.placeOrder('k', cart);
  const b = await service.placeOrder('k', cart);
  const c = await service.placeOrder('k', { sku: 1 });
  if (a !== b) throw new Error('retry is not same object reference: ' + a + ' vs ' + b);
  if (a.id !== c.id) throw new Error('third retry id mismatch');
  if (creates !== 1) throw new Error('creates=' + creates);
  console.log('  creates', creates, 'sameRef', a === b, 'id', a.id);
});

banner('2. concurrent coalesce');
await run('N=5 concurrent', async () => {
  let creates = 0;
  let release;
  const gate = new Promise(r => { release = r; });
  const service = new CheckoutService({
    async create(cart) {
      creates += 1;
      await gate;
      return { id: 'conc', cart };
    }
  });
  const ps = Array.from({ length: 5 }, () => service.placeOrder('k', { sku: 2 }));
  release();
  const results = await Promise.all(ps);
  const allSame = results.every(r => r === results[0]);
  if (!allSame) throw new Error('not all same reference');
  if (creates !== 1) throw new Error('creates=' + creates);
  console.log('  creates', creates, 'allSameRef', allSame);
});

banner('3. conflict');
await run('completed then different payload', async () => {
  let creates = 0;
  const service = new CheckoutService({
    async create(cart) {
      creates += 1;
      return { id: 'c' + creates, cart };
    }
  });
  const first = await service.placeOrder('k', { sku: 1 });
  let err;
  try {
    await service.placeOrder('k', { sku: 2 });
  } catch (e) { err = e; }
  if (!err) throw new Error('expected conflict');
  if (err.code !== 'IDEMPOTENCY_CONFLICT') throw new Error('code=' + err.code);
  if (creates !== 1) throw new Error('creates=' + creates);
  const retry = await service.placeOrder('k', { sku: 1 });
  if (retry !== first) throw new Error('original not preserved');
  console.log('  code', err.code, 'creates', creates);
});

await run('in-flight different payload conflicts without second create', async () => {
  let creates = 0;
  let release;
  const gate = new Promise(r => { release = r; });
  const started = Promise.withResolvers();
  const service = new CheckoutService({
    async create(cart) {
      creates += 1;
      started.resolve();
      await gate;
      return { id: 'inflight', cart };
    }
  });
  const firstP = service.placeOrder('k', { sku: 1 });
  await started.promise;
  let err;
  try {
    await service.placeOrder('k', { sku: 2 });
  } catch (e) { err = e; }
  if (!err) throw new Error('expected in-flight conflict');
  if (err.code !== 'IDEMPOTENCY_CONFLICT') throw new Error('code=' + err.code);
  release();
  const first = await firstP;
  if (first.id !== 'inflight') throw new Error('first failed');
  if (creates !== 1) throw new Error('creates=' + creates);
  console.log('  in-flight conflict code', err.code, 'creates', creates);
});

banner('4. failed creation does not poison');
await run('async throw then retry', async () => {
  let creates = 0;
  const service = new CheckoutService({
    async create(cart) {
      creates += 1;
      if (creates === 1) throw new Error('async fail');
      return { id: 'ok', cart };
    }
  });
  await service.placeOrder('k', { sku: 1 }).then(() => { throw new Error('should fail'); }, e => {
    if (e.message !== 'async fail') throw e;
  });
  const second = await service.placeOrder('k', { sku: 1 });
  if (second.id !== 'ok') throw new Error('id=' + second.id);
  if (creates !== 2) throw new Error('creates=' + creates);
  console.log('  creates', creates, 'id', second.id);
});

await run('sync throw from non-async create then retry', async () => {
  let creates = 0;
  const service = new CheckoutService({
    create(cart) {
      creates += 1;
      if (creates === 1) throw new Error('sync fail');
      return { id: 'recovered', cart };
    }
  });
  let firstErr;
  try {
    await service.placeOrder('k', { sku: 1 });
  } catch (e) { firstErr = e; }
  console.log('  firstErr', firstErr && firstErr.message, 'createsAfterFirst', creates);
  let secondErr;
  let second;
  try {
    second = await service.placeOrder('k', { sku: 1 });
  } catch (e) { secondErr = e; }
  console.log('  secondErr', secondErr && secondErr.message, 'second', second, 'creates', creates);
  if (secondErr) throw new Error('POISON: retry failed with ' + secondErr.message + ' creates=' + creates);
  if (creates !== 2) throw new Error('creates=' + creates);
});

await run('sync throw from create returning rejected? non-async return Promise.reject', async () => {
  let creates = 0;
  const service = new CheckoutService({
    create(cart) {
      creates += 1;
      if (creates === 1) return Promise.reject(new Error('rejected promise'));
      return Promise.resolve({ id: 'recovered', cart });
    }
  });
  let firstErr;
  try { await service.placeOrder('k', { sku: 1 }); } catch (e) { firstErr = e; }
  const second = await service.placeOrder('k', { sku: 1 });
  console.log('  firstErr', firstErr && firstErr.message, 'second', second.id, 'creates', creates);
  if (creates !== 2) throw new Error('creates=' + creates);
});

await run('async create delayed fail then retry in catch', async () => {
  let creates = 0;
  const service = new CheckoutService({
    async create(cart) {
      creates += 1;
      await Promise.resolve();
      if (creates === 1) throw new Error('delayed fail');
      return { id: 'ok', cart };
    }
  });
  try {
    await service.placeOrder('k', { sku: 1 });
  } catch (e) {
    const second = await service.placeOrder('k', { sku: 1 });
    if (second.id !== 'ok') throw new Error('id=' + second.id);
  }
  if (creates !== 2) throw new Error('creates=' + creates);
  console.log('  creates', creates);
});

banner('concurrent fail coalesced then later retry');
await run('two concurrent fail then third succeeds', async () => {
  let creates = 0;
  let release;
  const gate = new Promise(r => { release = r; });
  const service = new CheckoutService({
    async create(cart) {
      creates += 1;
      await gate;
      if (creates === 1) throw new Error('boom');
      return { id: 'after', cart };
    }
  });
  const p1 = service.placeOrder('k', { sku: 1 });
  const p2 = service.placeOrder('k', { sku: 1 });
  release();
  const r1 = await p1.then(v => ({ ok: v }), e => ({ err: e.message }));
  const r2 = await p2.then(v => ({ ok: v }), e => ({ err: e.message }));
  const p3 = await service.placeOrder('k', { sku: 1 });
  console.log('  r1', r1, 'r2', r2, 'p3', p3, 'creates', creates);
  if (r1.err !== 'boom' || r2.err !== 'boom') throw new Error('expected both boom');
  if (p3.id !== 'after') throw new Error('retry did not succeed');
  if (creates !== 2) throw new Error('creates=' + creates);
});

banner('JSON key order');
await run('semantically same cart different key order', async () => {
  let creates = 0;
  const service = new CheckoutService({
    async create(cart) {
      creates += 1;
      return { id: 'j', cart };
    }
  });
  await service.placeOrder('k', { sku: 1, qty: 2 });
  try {
    const r = await service.placeOrder('k', { qty: 2, sku: 1 });
    console.log('  treated as same payload, creates', creates, 'id', r.id);
  } catch (e) {
    console.log('  treated as conflict code', e.code, 'creates', creates);
  }
});

banner('queueMicrotask retry after rejection');
await run('microtask retry after async fail', async () => {
  let creates = 0;
  const service = new CheckoutService({
    async create(cart) {
      creates += 1;
      if (creates === 1) throw new Error('fail');
      return { id: 'ok', cart };
    }
  });
  const p = service.placeOrder('k', { sku: 1 });
